#!/usr/bin/env bash
# Shared prologue library for the tests/check_*.sh gates and their self-tests.
# Source-only: defining these functions is the whole effect, so each script
# keeps its own assertions and output while the repeated git-root prologue,
# the mktemp sandbox dance, the step status mapping, and the C++ g++ recipe
# live exactly once. A misquoted copy turned a gate into a silent no-op;
# one implementation keeps that to one place.
#
# Usage (from any tests/*.sh):
#     . "${BASH_SOURCE[0]%/*}/gate_lib.sh"
#
# Generated by omp (Qwen3.8-Flash-Next) without human creative authorship.
# SPDX-License-Identifier: LGPL-2.1-or-later

# gate_root LABEL — set and export ROOT to the git toplevel and cd there.
# Outside a checkout, print the standard SKIP line for LABEL and return 125,
# so the caller writes exactly: gate_root 'my gate' || exit $?
gate_root() {
    ROOT=$(git rev-parse --show-toplevel 2>/dev/null) || {
        printf 'SKIP  %s (not inside a git checkout)\n' "$1"
        return 125
    }
    export ROOT
    cd "$ROOT" || return 1
}

# gate_top — set ROOT to the checkout root as seen from this file's own
# location (one level above tests/), for scripts that locate their siblings
# by path instead of through git.
gate_top() {
    ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
}

# gate_sandbox PREFIX — create PREFIX.XXXXXX under a base both this shell and
# the native tools resolve: MSYS child shells default TMP/TEMP to /tmp while
# native tools map it elsewhere, so when cygpath and USERPROFILE exist the
# Windows-form per-user home is the base, otherwise ${TMPDIR:-/tmp}. Sets
# `tmp` to the new directory and installs the EXIT trap that removes it;
# returns non-zero when mktemp failed.
gate_sandbox() {
    local base
    if command -v cygpath >/dev/null 2>&1 && [ -n "${USERPROFILE:-}" ]; then
        base=$(cygpath -w "$USERPROFILE")
    else
        base=${TMPDIR:-/tmp}
    fi
    tmp=$(mktemp -d "$base/$1.XXXXXX") || return 1
    trap 'rm -rf "$tmp"' EXIT
}

# gate_run_bounded SECONDS CMD... — run CMD in its own session (setsid) when
# available, so the deadline can take the whole session down: a hung Wine
# grandchild (wine -> winedbg) otherwise holds the prefix past the step.
# Returns the command's status, or 124 when the watchdog had to kill it.
# Needs BUILD_DIR set for the marker file.
gate_run_bounded() {
    local seconds=$1
    shift

    if ! command -v setsid >/dev/null 2>&1; then
        "$@"
        return
    fi

    setsid bash -c 'set -u; "$@"' _ "$@" &
    local pid=$!
    local marker="$BUILD_DIR/hung.$$"
    local watchdog

    # The watchdog gets its own session too: killing it with `kill $watchdog`
    # would leave its `sleep` child holding the run's stdout, so the pipeline
    # that started the suite would not finish until the deadline passed.
    setsid bash -c '
        sleep "$1"
        : >"$2"
        kill -TERM -- "-$3" 2>/dev/null
        sleep 5
        kill -KILL -- "-$3" 2>/dev/null
    ' _ "$seconds" "$marker" "$pid" &
    watchdog=$!

    local status=0
    ACTIVE_STEP=$pid
    ACTIVE_WATCHDOG=$watchdog
    wait "$pid" || status=$?
    ACTIVE_STEP=
    ACTIVE_WATCHDOG=
    kill -TERM -- "-$watchdog" 2>/dev/null
    wait "$watchdog" 2>/dev/null

    if [ -e "$marker" ]; then
        rm -f "$marker"
        return 124
    fi
    return "$status"
}

# gate_run NAME TIMEOUT CMD... — run CMD bounded and print the step line in
# the wording both gates pin: PASS for 0, HANG for the watchdog's 124, SKIP
# for the not-applicable 125, FAIL (exit N) otherwise. Returns the status so
# the caller moves its own counters.
gate_run() {
    local name=$1 timeout=$2
    shift 2
    local status=0
    gate_run_bounded "$timeout" "$@" || status=$?
    case "$status" in
        0)
            printf 'PASS  %s\n' "$name"
            ;;
        124)
            printf 'HANG  %s (killed after %ss; rerun by hand: %s)\n' \
                "$name" "$timeout" "$*"
            return 124
            ;;
        125)
            printf 'SKIP  %s (not applicable here)\n' "$name"
            ;;
        *)
            printf 'FAIL  %s (exit %s)\n' "$name" "$status"
            return "$status"
            ;;
    esac
    return 0
}

# cpp_test SRC CC CC_EXTRA INCLUDES LIBS [wine] — the one g++ recipe behind
# the five pure-C++ helper tests. CC is the compiler (host g++ or the
# mingw-w64 cross); CC_EXTRA, INCLUDES and LIBS are space-separated flag
# words passed through unquoted (e.g. "-static", "-I json/single_include",
# "-luser32 -lgdi32", "-pthread -include cstdint"). The binary lands in
# $BUILD_DIR named after SRC; with the trailing word `wine` the build is a
# .exe run through WINEDEBUG=-all wine, else the host binary runs directly.
cpp_test() {
    local src=$1 cc=$2 cc_extra=$3 includes=$4 libs=$5
    local wine=${6:-}
    local out="$BUILD_DIR/$(basename "$src" .cpp)"
    if [ -n "$wine" ]; then
        out="$out.exe"
    fi
    # shellcheck disable=SC2086
    "$cc" -std=c++17 -O1 $cc_extra $includes "$src" $libs -o "$out" ||
        return $?
    if [ -n "$wine" ]; then
        WINEDEBUG=-all wine "$out"
    else
        "$out"
    fi
}
